/// A block's hardness; `None` for `Unknown`.
pub fn hardness(block: BlockKind) -> Option<f32> {
    if let BlockKind::Unknown(_) = block {
        return None;
    }
    usize::try_from(block.id())
        .ok()
        .and_then(|i| HARDNESS.get(i))
        .copied()
}

/// Whether a block drops only to its correct tool; `None` for `Unknown`.
pub fn needs_correct_tool(block: BlockKind) -> Option<bool> {
    if let BlockKind::Unknown(_) = block {
        return None;
    }
    usize::try_from(block.id())
        .ok()
        .and_then(|i| NEEDS_CORRECT_TOOL.get(i))
        .copied()
}
